/* Codeditor courses — HTML, CSS, Interactive pages (DOM) */
(() => {
  const { e, tip, pre, tryit, read, quiz, predict, code, course } = Q.kit;
  const rgb = (hex) => { const n = parseInt(hex.replace('#', ''), 16); return `rgb(${(n >> 16) & 255}, ${(n >> 8) & 255}, ${n & 255})`; };

  /* ============================== HTML ============================== */
  course({
    id: 'html', lang: 'html', order: 1, title: 'HTML: Build Pages', badge: 'HTML', color: '#f97316', ext: 'html', run: 'web', mode: 'html',
    desc: 'Structure for the web', desc2: 'HTML describes what’s on a page. You’ll finish by building a landing page for your own game.',
    lessons: [
      { id: 'tags', title: 'Your first tags', xp: 20, recap: 'Tags wrap content: <code>&lt;h1&gt;</code> opens, <code>&lt;/h1&gt;</code> closes.', steps: [
        read('Pages are made of tags', `<p>Every web page — including the page your browser game lives on — is written in <b>HTML</b>. HTML doesn’t do math or logic; it <b>labels</b> content: “this is a heading”, “this is a button”, “this is a picture”.</p><p>You label things with <b>tags</b> in angle brackets:</p>${pre('<h1>Space Raiders</h1>')}<ul><li><code>&lt;h1&gt;</code> <b>opens</b> a big heading.</li><li><code>&lt;/h1&gt;</code> (with a slash) <b>closes</b> it.</li><li>Everything in between is the <b>content</b>.</li></ul>`),
        quiz('Which of these is a <b>closing</b> tag?', ['<h1>', '</h1>', '<h1/>', '(h1)'], 1, 'The slash <code>/</code> marks the end of an element.'),
        read('Six sizes of heading', `<p>Headings go from <code>&lt;h1&gt;</code> (biggest, the page title) down to <code>&lt;h6&gt;</code> (smallest). Use them like an outline:</p>${tryit('<h1>Space Raiders</h1>\n<h2>How to play</h2>\n<h3>Controls</h3>')}${tip('Click <b>Try it</b> to put example code in your editor, then watch the live preview below the task.')}`),
        quiz('Which heading would you use for the name of your whole game?', ['<h6>', '<h3>', '<h1>', '<head>'], 2, 'h1 is the main title. Use one per page.'),
        code({ task: 'Make a big heading that says exactly <b>Space Raiders</b>.', starter: '<!-- write your heading below -->\n\n', hints: ['Start with <code>&lt;h1&gt;</code> and end with <code>&lt;/h1&gt;</code>.', 'Type: <code>&lt;h1&gt;Space Raiders&lt;/h1&gt;</code>'], solution: '<h1>Space Raiders</h1>\n',
          check: (r, H) => { const h = H.el(r, 'h1'); if (!h) return 'I can’t find an <code>&lt;h1&gt;</code> yet.'; return H.text(r, 'h1') === 'Space Raiders' || `Your heading says “${e(H.text(r, 'h1'))}” — make it say exactly “Space Raiders”.`; }, success: 'You just wrote your first HTML! 🎉' }),
        code({ keep: true, task: 'Under it, add an <code>&lt;h2&gt;</code> that says <b>How to play</b>, and under that an <code>&lt;h3&gt;</code> that says <b>Controls</b>.', hints: ['Each heading goes on its own line, in order h1 → h2 → h3.'], solution: '<h1>Space Raiders</h1>\n<h2>How to play</h2>\n<h3>Controls</h3>\n',
          check: (r, H) => (!H.el(r, 'h1') ? 'Keep your h1.' : H.text(r, 'h2') !== 'How to play' ? 'Add <code>&lt;h2&gt;How to play&lt;/h2&gt;</code>.' : H.text(r, 'h3') !== 'Controls' ? 'Add <code>&lt;h3&gt;Controls&lt;/h3&gt;</code>.' : true) }),
      ] },
      { id: 'text', title: 'Paragraphs & emphasis', xp: 20, recap: '<code>&lt;p&gt;</code> for paragraphs; <code>&lt;strong&gt;</code> = important; <code>&lt;em&gt;</code> = emphasis. Close nested tags in reverse order.', steps: [
        read('Paragraphs', `<p>Normal text goes in <code>&lt;p&gt;</code> (paragraph) tags. The browser ignores extra spaces and line breaks in your code — each <code>&lt;p&gt;</code> becomes its own block with space around it.</p>${tryit('<p>Defend the galaxy from waves of invaders.</p>\n<p>Survive as long as you can!</p>')}`),
        read('Important words', `<p>Inside a paragraph, wrap words in <code>&lt;strong&gt;</code> to mark them <b>important</b> (bold), or <code>&lt;em&gt;</code> for <i>emphasis</i> (italic):</p>${pre('<p>Collect <strong>power-ups</strong> to fire <em>faster</em>.</p>')}<p>A tag inside another tag is <b>nested</b>. Close them in reverse order, like stacking boxes: last opened, first closed.</p>`),
        quiz('Which nesting is correct?', ['<p><strong>Hi</p></strong>', '<p><strong>Hi</strong></p>', '<strong><p>Hi</strong></p>'], 1, 'strong opened last, so it closes first.'),
        code({ task: 'Write a paragraph describing your dream game in one sentence. Make the genre (like <i>platformer</i>) <code>&lt;strong&gt;</code>.', starter: '', hints: ['<code>&lt;p&gt;A &lt;strong&gt;platformer&lt;/strong&gt; about a jumping cat.&lt;/p&gt;</code>'], solution: '<p>A <strong>platformer</strong> about a cat who can double jump.</p>\n',
          check: (r, H) => { const p = H.el(r, 'p'); if (!p) return 'Add a <code>&lt;p&gt;</code> paragraph.'; if (!p.querySelector('strong')) return 'Put a <code>&lt;strong&gt;</code> tag <i>inside</i> your paragraph.'; return p.textContent.trim().length > 10 || 'Write a full sentence.'; } }),
        code({ keep: true, task: 'Add a second paragraph that uses <code>&lt;em&gt;</code> on at least one word.', hints: ['A new <code>&lt;p&gt;…&lt;/p&gt;</code> with <code>&lt;em&gt;word&lt;/em&gt;</code> inside.'], solution: '<p>A <strong>platformer</strong> about a cat who can double jump.</p>\n<p>Every level is <em>harder</em> than the last.</p>\n',
          check: (r, H) => (H.els(r, 'p').length < 2 ? 'Add a second <code>&lt;p&gt;</code>.' : !H.els(r, 'p')[1].querySelector('em') ? 'Put an <code>&lt;em&gt;</code> inside the second paragraph.' : true) }),
      ] },
      { id: 'links', title: 'Links & images', xp: 25, recap: '<code>&lt;a href&gt;</code> links; <code>&lt;img src alt&gt;</code> shows a picture and has no closing tag.', steps: [
        read('Attributes', `<p>Tags can carry extra settings called <b>attributes</b>, written inside the opening tag as <code>name="value"</code>:</p>${pre('<a href="https://itch.io">Play more indie games</a>')}<p><code>href</code> is where the link goes. The text between the tags is what people click.</p>`),
        read('Images', `<p>Images use <code>src</code> (which file) and <code>alt</code> (a description for people who can’t see it):</p>${pre('<img src="ship.png" alt="A red spaceship">')}${tip('<code>&lt;img&gt;</code> has no closing tag — there’s no content inside it. Tags like this are called <b>void</b> elements.')}`),
        quiz('What is the <code>alt</code> attribute for?', ['Making the image bigger', 'Describing the image for screen readers and if it fails to load', 'Choosing the image file', 'Linking to another page'], 1, 'Good alt text makes your site usable by everyone.'),
        code({ task: 'Make a link to <code>https://example.com</code> with the text <b>Play now</b>.', starter: '', hints: ['Use the <code>a</code> tag with an <code>href</code> attribute.', '<code>&lt;a href="https://example.com"&gt;Play now&lt;/a&gt;</code>'], solution: '<a href="https://example.com">Play now</a>\n',
          check: (r, H) => { const a = H.el(r, 'a'); if (!a) return 'I don’t see an <code>&lt;a&gt;</code> tag.'; if (!/^https:\/\/example\.com\/?$/.test(a.getAttribute('href') || '')) return 'Set <code>href="https://example.com"</code>.'; return a.textContent.trim() === 'Play now' || 'The link text should be “Play now”.'; } }),
        code({ keep: true, task: 'Add an image with <code>src="https://picsum.photos/200"</code> and a helpful <code>alt</code> description.', hints: ['<code>&lt;img src="https://picsum.photos/200" alt="Game screenshot"&gt;</code>'], solution: '<a href="https://example.com">Play now</a>\n<img src="https://picsum.photos/200" alt="Game screenshot">\n',
          check: (r, H) => { const i = H.el(r, 'img'); if (!i) return 'Add an <code>&lt;img&gt;</code> tag.'; if (!(i.getAttribute('src') || '').includes('picsum.photos')) return 'Use the src from the task.'; return (i.getAttribute('alt') || '').trim().length >= 3 || 'Give the image an alt text (at least 3 characters).'; } }),
        code({ keep: true, task: 'Make the <b>image itself</b> clickable by moving it <i>inside</i> the link (replace the “Play now” text with the image).', hints: ['<code>&lt;a href="…"&gt;&lt;img …&gt;&lt;/a&gt;</code>'], solution: '<a href="https://example.com"><img src="https://picsum.photos/200" alt="Game screenshot"></a>\n',
          check: (r, H) => (H.el(r, 'a img') ? true : 'Put the <code>&lt;img&gt;</code> between <code>&lt;a …&gt;</code> and <code>&lt;/a&gt;</code>.'), success: 'Nesting tags lets you combine them — a clickable image is a link containing an image.' }),
      ] },
      { id: 'lists', title: 'Lists', xp: 20, recap: '<code>&lt;ul&gt;</code> = bullets, <code>&lt;ol&gt;</code> = numbers, each item in <code>&lt;li&gt;</code>.', steps: [
        read('Bullets and numbers', `<p><code>&lt;ul&gt;</code> is an <b>unordered</b> list (bullets). <code>&lt;ol&gt;</code> is an <b>ordered</b> list (1, 2, 3). Every item goes in an <code>&lt;li&gt;</code> (list item).</p>${tryit('<ol>\n  <li>Choose a ship</li>\n  <li>Destroy the asteroids</li>\n  <li>Beat the boss</li>\n</ol>')}`),
        quiz('You’re listing the steps of a tutorial in order. Which list?', ['<ul>', '<ol>', '<li>', '<list>'], 1, '“o” for ordered → numbers.'),
        code({ task: 'Make a bulleted list (<code>ul</code>) of your game’s <b>3</b> controls (for example “Arrow keys: move”).', starter: '<h3>Controls</h3>\n', hints: ['Wrap everything in <code>&lt;ul&gt;…&lt;/ul&gt;</code>.', 'Each control goes in its own <code>&lt;li&gt;…&lt;/li&gt;</code>.'], solution: '<h3>Controls</h3>\n<ul>\n  <li>Arrow keys: move</li>\n  <li>Space: shoot</li>\n  <li>P: pause</li>\n</ul>\n',
          check: (r, H) => { const ul = H.el(r, 'ul'); if (!ul) return 'Start with a <code>&lt;ul&gt;</code>.'; const n = ul.querySelectorAll('li').length; return n === 3 || `Your list has ${n} item${n === 1 ? '' : 's'} — make it exactly 3.`; } }),
        code({ keep: true, task: 'Below it, add an <b>ordered</b> list of the 3 worlds in your game.', hints: ['Same idea, with <code>&lt;ol&gt;</code>.'], solution: '<h3>Controls</h3>\n<ul>\n  <li>Arrow keys: move</li>\n  <li>Space: shoot</li>\n  <li>P: pause</li>\n</ul>\n<ol>\n  <li>Ice Moon</li>\n  <li>Lava Belt</li>\n  <li>The Core</li>\n</ol>\n',
          check: (r, H) => { const ol = H.el(r, 'ol'); if (!ol) return 'Add an <code>&lt;ol&gt;</code>.'; return ol.querySelectorAll('li').length === 3 || 'Give the ordered list 3 items.'; } }),
      ] },
      { id: 'skeleton', title: 'A complete page', xp: 25, recap: 'Every page: doctype, &lt;html&gt;, &lt;head&gt; (info + title), &lt;body&gt; (what you see).', steps: [
        read('The page skeleton', `<p>So far you’ve written pieces. A real page has a standard frame around them:</p>${pre('<!DOCTYPE html>\n<html>\n<head>\n  <title>Space Raiders</title>\n</head>\n<body>\n  <h1>Space Raiders</h1>\n</body>\n</html>')}<ul><li><code>&lt;!DOCTYPE html&gt;</code> tells the browser “this is modern HTML”.</li><li><code>&lt;head&gt;</code> holds information <i>about</i> the page. The <code>&lt;title&gt;</code> shows in the browser tab.</li><li><code>&lt;body&gt;</code> holds everything you see.</li></ul>`),
        quiz('Where does the <code>&lt;title&gt;</code> go?', ['In <body>', 'In <head>', 'After </html>', 'Anywhere'], 1, 'Page information belongs in the head.'),
        quiz('Your game’s <code>&lt;canvas&gt;</code> should go in…', ['<head>', '<body>', '<title>', '<!DOCTYPE>'], 1, 'Anything visible goes in the body.'),
        code({ task: 'Build a full page skeleton with the title <b>My Game</b> and an <code>&lt;h1&gt;</code> in the body.', starter: '<!DOCTYPE html>\n<html>\n\n</html>\n', hints: ['Inside &lt;html&gt;, add &lt;head&gt; then &lt;body&gt;.', 'The head needs <code>&lt;title&gt;My Game&lt;/title&gt;</code>.'], solution: '<!DOCTYPE html>\n<html>\n<head>\n  <title>My Game</title>\n</head>\n<body>\n  <h1>My Game</h1>\n</body>\n</html>\n',
          check: (r) => { if (!/<head[\s>]/i.test(r.code)) return 'Add a <code>&lt;head&gt;</code> section.'; if (r.doc.title !== 'My Game') return 'Set the title to exactly “My Game”.'; if (!/<body[\s>]/i.test(r.code)) return 'Add a <code>&lt;body&gt;</code>.'; return !!r.doc.body.querySelector('h1') || 'Put an <code>&lt;h1&gt;</code> inside the body.'; } }),
        read('Two head tags every page needs', `<p>Add these inside <code>&lt;head&gt;</code> on every page you make:</p>${pre('<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">')}<p>The first makes emoji and accents display correctly. The second makes your page fit phone screens.</p>${tip('In a real .html file, type <code>!</code> and press <b>Tab</b> — Emmet writes the whole skeleton for you.')}`),
        code({ keep: true, task: 'Add <code>&lt;meta charset="UTF-8"&gt;</code> to your head.', hints: ['Put it on the line before <code>&lt;title&gt;</code>.'], solution: '<!DOCTYPE html>\n<html>\n<head>\n  <meta charset="UTF-8">\n  <title>My Game</title>\n</head>\n<body>\n  <h1>My Game</h1>\n</body>\n</html>\n',
          check: (r) => (/<head[^>]*>[\s\S]*<meta\s+charset=["']?utf-8["']?\s*\/?>[\s\S]*<\/head>/i.test(r.code) ? true : 'Add <code>&lt;meta charset="UTF-8"&gt;</code> inside the head.') }),
      ] },
      { id: 'boxes', title: 'Boxes, classes & ids', xp: 25, recap: '<code>&lt;div&gt;</code> groups things; <code>class</code> names groups; <code>id</code> names one unique element.', steps: [
        read('Grouping with div', `<p>A <code>&lt;div&gt;</code> is an invisible box that groups other elements. It doesn’t mean anything by itself — it’s for layout and styling. <code>&lt;span&gt;</code> is the same idea for a few words inside a line.</p>${pre('<div>\n  <h2>Player 1</h2>\n  <p>Score: <span>1200</span></p>\n</div>')}`),
        read('Naming things: class and id', `<p>To style or control an element later (with CSS or JavaScript), give it a name:</p><ul><li><code>class="card"</code> — a group name. Many elements can share it.</li><li><code>id="score"</code> — a unique name. Only one element per page.</li></ul>${pre('<div class="card">…</div>\n<div class="card">…</div>\n<span id="score">0</span>')}${tip('Your game’s JavaScript will find things by id, like <code>document.querySelector("#score")</code>.')}`),
        quiz('You have 5 enemy cards that should all look the same. Use…', ['id="enemy" on each', 'class="enemy" on each', 'name="enemy"', 'style="enemy"'], 1, 'Ids must be unique; classes are for groups.'),
        code({ task: 'Make two <code>&lt;div class="card"&gt;</code> boxes, each containing an <code>&lt;h2&gt;</code> with a character name.', starter: '', hints: ['<code>&lt;div class="card"&gt;&lt;h2&gt;Knight&lt;/h2&gt;&lt;/div&gt;</code> twice.'], solution: '<div class="card">\n  <h2>Knight</h2>\n</div>\n<div class="card">\n  <h2>Archer</h2>\n</div>\n',
          check: (r, H) => { const c = H.els(r, 'div.card'); if (c.length !== 2) return `I found ${c.length} <code>div.card</code> — make 2.`; return c.every((d) => d.querySelector('h2')?.textContent.trim()) || 'Each card needs an &lt;h2&gt; with a name.'; } }),
        code({ keep: true, task: 'Inside the first card, add <code>&lt;p&gt;HP: &lt;span id="hp"&gt;100&lt;/span&gt;&lt;/p&gt;</code>.', hints: ['Put it right after the first card’s &lt;h2&gt;.'], solution: '<div class="card">\n  <h2>Knight</h2>\n  <p>HP: <span id="hp">100</span></p>\n</div>\n<div class="card">\n  <h2>Archer</h2>\n</div>\n',
          check: (r, H) => (!H.el(r, '#hp') ? 'Add a <code>&lt;span id="hp"&gt;</code>.' : H.text(r, '#hp') !== '100' ? 'The span should contain 100.' : !H.els(r, 'div.card')[0].querySelector('#hp') ? 'Put it inside the <b>first</b> card.' : true) }),
      ] },
      { id: 'forms', title: 'Buttons & forms', xp: 25, recap: '<code>&lt;input type=…&gt;</code> collects data; <code>&lt;label for&gt;</code> describes it; <code>&lt;button&gt;</code> acts.', steps: [
        read('Getting input', `<p>Forms let players type and click. The <code>type</code> attribute changes what an input looks like:</p>${tryit('<label for="name">Player name</label>\n<input id="name" type="text" placeholder="Ada">\n<input type="range" min="0" max="10">\n<input type="color">\n<button>Start</button>')}`),
        read('Labels matter', `<p>A <code>&lt;label&gt;</code> whose <code>for</code> matches an input’s <code>id</code> is linked to it: clicking the label focuses the input, and screen readers announce it.</p>${pre('<label for="vol">Volume</label>\n<input id="vol" type="range" min="0" max="100">')}`),
        quiz('Which input makes a checkbox?', ['<input type="check">', '<checkbox>', '<input type="checkbox">', '<input box>'], 2),
        code({ task: 'Make a settings form: a <b>range</b> slider for volume (<code>min="0" max="100"</code>) with a <code>&lt;label&gt;</code> linked to it, and a <code>&lt;button&gt;</code> that says <b>Save</b>.', starter: '<form>\n\n</form>\n', hints: ['<code>&lt;label for="vol"&gt;Volume&lt;/label&gt;</code>', '<code>&lt;input id="vol" type="range" min="0" max="100"&gt;</code> then the button.'], solution: '<form>\n  <label for="vol">Volume</label>\n  <input id="vol" type="range" min="0" max="100">\n  <button>Save</button>\n</form>\n',
          check: (r, H) => { const i = H.el(r, 'input[type="range"]'); if (!i) return 'Add <code>&lt;input type="range"&gt;</code>.'; if (i.min !== '0' || i.max !== '100') return 'Set <code>min="0"</code> and <code>max="100"</code>.'; const l = H.el(r, 'label'); if (!l || l.htmlFor !== i.id || !i.id) return 'Link the label to the input: its <code>for</code> must match the input’s <code>id</code>.'; const b = H.el(r, 'button'); return (b && b.textContent.trim() === 'Save') || 'Add a button that says “Save”.'; } }),
        code({ keep: true, task: 'Add a checkbox labelled <b>Show FPS</b> to the same form.', hints: ['<code>&lt;input id="fps" type="checkbox"&gt;</code> with <code>&lt;label for="fps"&gt;Show FPS&lt;/label&gt;</code>'], solution: '<form>\n  <label for="vol">Volume</label>\n  <input id="vol" type="range" min="0" max="100">\n  <label for="fps">Show FPS</label>\n  <input id="fps" type="checkbox">\n  <button>Save</button>\n</form>\n',
          check: (r, H) => { const c = H.el(r, 'input[type="checkbox"]'); if (!c) return 'Add a checkbox.'; const l = [...r.doc.querySelectorAll('label')].find((x) => x.htmlFor === c.id && c.id); return (l && /show fps/i.test(l.textContent)) || 'Give the checkbox a linked label that says “Show FPS”.'; } }),
      ] },
      { id: 'semantic', title: 'Page layout tags', xp: 25, recap: 'header, nav, main, section and footer describe the parts of a page.', steps: [
        read('Meaningful sections', `<p>Instead of a pile of <code>&lt;div&gt;</code>s, HTML has tags that say what each part <b>is</b>. Search engines and screen readers rely on them.</p>${pre('<header>Logo and title</header>\n<nav>Links to other pages</nav>\n<main>\n  <section>Trailer</section>\n  <section>Features</section>\n</main>\n<footer>© 2026 My Studio</footer>')}`),
        quiz('Where should the main menu links go?', ['<footer>', '<nav>', '<aside>', '<title>'], 1),
        quiz('How many <code>&lt;main&gt;</code> elements should a page have?', ['As many as you like', 'Exactly one', 'None', 'One per section'], 1, 'main is the page’s unique main content.'),
        code({ task: 'Create a page with a <code>header</code> (containing an h1), a <code>main</code> with two <code>section</code>s, and a <code>footer</code>.', starter: '', hints: ['Four parts in order: header, main (with sections inside), footer.'], solution: '<header>\n  <h1>Space Raiders</h1>\n</header>\n<main>\n  <section>Trailer</section>\n  <section>Features</section>\n</main>\n<footer>© 2026</footer>\n',
          check: (r, H) => (!H.el(r, 'header h1') ? 'Add a <code>&lt;header&gt;</code> with an <code>&lt;h1&gt;</code> inside.' : !H.el(r, 'main') ? 'Add a <code>&lt;main&gt;</code>.' : H.els(r, 'main > section').length !== 2 ? 'Put two <code>&lt;section&gt;</code>s inside main.' : !H.el(r, 'footer') ? 'Add a <code>&lt;footer&gt;</code>.' : true) }),
      ] },
      { id: 'project', title: 'Project: your game’s landing page', xp: 60, recap: 'You combined headings, text, images, links, lists, classes and layout tags into a real page.', steps: [
        read('Build a landing page', `<p>Every game on itch.io or Steam has a page that sells it. You’ll build one in three steps, using everything from this course. Make up any game you like!</p>`),
        code({ task: '<b>Step 1.</b> Write the full skeleton (doctype, head with charset and a title, body). In the body add a <code>header</code> with your game’s name as an <code>h1</code> and a one-sentence tagline in a <code>p</code>.', starter: '', hints: ['Start from the skeleton lesson.', 'header → h1 + p'], solution: '<!DOCTYPE html>\n<html>\n<head>\n  <meta charset="UTF-8">\n  <title>Space Raiders</title>\n</head>\n<body>\n  <header>\n    <h1>Space Raiders</h1>\n    <p>Defend the last colony from endless waves.</p>\n  </header>\n</body>\n</html>\n',
          check: (r, H) => (!r.doc.title ? 'Give the page a <code>&lt;title&gt;</code>.' : !/charset/i.test(r.code) ? 'Add the charset meta tag.' : !H.el(r, 'body > header h1') ? 'Add a header with an h1 in the body.' : !H.el(r, 'header p') ? 'Add a tagline paragraph in the header.' : true) }),
        code({ keep: true, task: '<b>Step 2.</b> After the header add a <code>main</code> with a <code>section</code> containing an <code>h2</code> “Features” and a <code>ul</code> of at least 3 features.', hints: ['main → section → h2 + ul → li × 3'], solution: '<!DOCTYPE html>\n<html>\n<head>\n  <meta charset="UTF-8">\n  <title>Space Raiders</title>\n</head>\n<body>\n  <header>\n    <h1>Space Raiders</h1>\n    <p>Defend the last colony from endless waves.</p>\n  </header>\n  <main>\n    <section>\n      <h2>Features</h2>\n      <ul>\n        <li>12 weapons</li>\n        <li>Boss fights</li>\n        <li>Online high scores</li>\n      </ul>\n    </section>\n  </main>\n</body>\n</html>\n',
          check: (r, H) => (!H.el(r, 'main section') ? 'Add main → section.' : !/features/i.test(H.text(r, 'main section h2')) ? 'Give the section an h2 “Features”.' : H.els(r, 'main section ul li').length < 3 ? 'List at least 3 features.' : true) }),
        code({ keep: true, task: '<b>Step 3.</b> Add a <b>Play now</b> link (<code>class="play"</code>) inside main, and a <code>footer</code> with © and your studio name.', hints: ['<code>&lt;a class="play" href="#"&gt;Play now&lt;/a&gt;</code>', 'Footer goes after main, before &lt;/body&gt;.'], solution: '<!DOCTYPE html>\n<html>\n<head>\n  <meta charset="UTF-8">\n  <title>Space Raiders</title>\n</head>\n<body>\n  <header>\n    <h1>Space Raiders</h1>\n    <p>Defend the last colony from endless waves.</p>\n  </header>\n  <main>\n    <section>\n      <h2>Features</h2>\n      <ul>\n        <li>12 weapons</li>\n        <li>Boss fights</li>\n        <li>Online high scores</li>\n      </ul>\n    </section>\n    <a class="play" href="#">Play now</a>\n  </main>\n  <footer>© 2026 Nova Studio</footer>\n</body>\n</html>\n',
          check: (r, H) => (!H.el(r, 'main a.play') ? 'Add <code>&lt;a class="play"&gt;</code> inside main.' : !/play now/i.test(H.text(r, 'a.play')) ? 'The link should say “Play now”.' : !H.el(r, 'footer') ? 'Add a footer.' : !/©/.test(H.text(r, 'footer')) ? 'Put a © in the footer.' : true), success: 'A real landing page! Next, the CSS course makes it look amazing.' }),
      ] },
    ],
  });

  /* ============================== CSS ============================== */
  const page = (body) => `<!DOCTYPE html><html><head><style>body{font-family:system-ui;padding:12px}</style></head><body>${body}</body></html>`;
  course({
    id: 'css', lang: 'css', order: 1, title: 'CSS: Style & Animate', badge: 'CSS', color: '#3b82f6', ext: 'css', run: 'web', mode: 'css',
    desc: 'Colors, layout, motion', desc2: 'Make pages look great — and finish with an animated arcade title screen.', related: ['html'],
    lessons: [
      { id: 'rules', title: 'Selectors & colors', xp: 20, recap: '<code>selector { property: value; }</code>', steps: [
        read('Style rules', `<p>HTML says <i>what</i> things are. <b>CSS</b> says how they <b>look</b>. A rule picks elements with a <b>selector</b>, then sets <b>property: value</b> pairs:</p>${pre('h1 {\n  color: tomato;\n  background-color: black;\n}')}<p>This rule makes every <code>&lt;h1&gt;</code> tomato-red on black.</p>`),
        read('Writing colors', `<p>Colors can be written several ways:</p>${pre('color: red;                  /* one of 140 names */\ncolor: #ff6347;              /* hex: red, green, blue */\ncolor: rgb(255, 99, 71);     /* 0–255 each */')}${tip('Forgetting the semicolon <code>;</code> after a value is the most common CSS bug.')}`),
        quiz('In <code>p { color: blue; }</code>, what is <code>p</code>?', ['A property', 'A value', 'A selector', 'A comment'], 2, 'The selector chooses which elements get the style.'),
        code({ page: page('<h1>Space Raiders</h1><p>Press start</p>'), task: 'Make the <code>h1</code> text <b>red</b>.', starter: '/* style the h1 */\n', hints: ['<code>h1 { color: red; }</code>'], solution: 'h1 {\n  color: red;\n}\n',
          check: (r) => r.css('h1', 'color') === 'rgb(255, 0, 0)' || 'The h1 isn’t red yet. Check your selector and spelling.' }),
        code({ page: page('<h1>Space Raiders</h1><p>Press start</p>'), keep: true, task: 'Give the whole page (<code>body</code>) a background of <code>#0b1020</code> and make paragraphs <code>white</code>.', hints: ['A new rule: <code>body { background-color: #0b1020; }</code>', 'And: <code>p { color: white; }</code>'], solution: 'h1 {\n  color: red;\n}\n\nbody {\n  background-color: #0b1020;\n}\n\np {\n  color: white;\n}\n',
          check: (r) => (r.css('body', 'background-color') !== rgb('#0b1020') ? 'Set the body background to <code>#0b1020</code>.' : r.css('p', 'color') !== 'rgb(255, 255, 255)' ? 'Make the <code>p</code> text white.' : true) }),
      ] },
      { id: 'box', title: 'The box model', xp: 25, recap: 'content → padding → border → margin.', steps: [
        read('Everything is a box', `<p>Every element is a rectangle with layers, from the inside out:</p>${pre('┌──────────── margin ────────────┐\n│ ┌────────── border ──────────┐ │\n│ │ ┌──────── padding ───────┐ │ │\n│ │ │        content         │ │ │\n│ │ └────────────────────────┘ │ │\n│ └────────────────────────────┘ │\n└────────────────────────────────┘')}<ul><li><b>padding</b> — space <i>inside</i>, around the content</li><li><b>border</b> — the line around it</li><li><b>margin</b> — space <i>outside</i>, pushing neighbors away</li></ul>`),
        quiz('You want more space between a card’s text and its border. Which property?', ['margin', 'padding', 'gap', 'border'], 1),
        quiz('Two cards are touching. You want space <b>between</b> them. Which property?', ['padding', 'margin', 'border', 'width'], 1),
        code({ page: page('<div class="card">Knight · HP 100</div>'), task: 'Give <code>.card</code> a <code>padding</code> of <b>20px</b>, a <b>2px solid</b> border, and a <code>border-radius</code> of <b>8px</b>.', starter: '.card {\n  \n}\n', hints: ['The dot in <code>.card</code> selects class="card".', '<code>border: 2px solid gold;</code>'], solution: '.card {\n  padding: 20px;\n  border: 2px solid gold;\n  border-radius: 8px;\n}\n',
          check: (r) => (r.css('.card', 'padding-top') !== '20px' ? 'Set <code>padding: 20px;</code>' : r.css('.card', 'border-top-width') !== '2px' || r.css('.card', 'border-top-style') !== 'solid' ? 'Add <code>border: 2px solid …;</code>' : r.css('.card', 'border-top-left-radius') !== '8px' ? 'Add <code>border-radius: 8px;</code>' : true) }),
        read('Sizes that behave', `<p>By default, <code>width</code> sets only the content width — padding and border are added <i>on top</i>, which makes math confusing. Almost every project starts with:</p>${pre('* {\n  box-sizing: border-box;\n}')}<p>Now <code>width: 200px</code> means the whole box is 200px, padding and border included. (<code>*</code> selects every element.)</p>`),
        code({ page: page('<div class="card">Knight · HP 100</div>'), keep: true, task: 'Add the <code>box-sizing: border-box</code> rule for every element, and give <code>.card</code> a <code>width</code> of <b>200px</b>.', hints: ['<code>* { box-sizing: border-box; }</code>'], solution: '* {\n  box-sizing: border-box;\n}\n\n.card {\n  width: 200px;\n  padding: 20px;\n  border: 2px solid gold;\n  border-radius: 8px;\n}\n',
          check: (r) => (r.css('.card', 'box-sizing') !== 'border-box' ? 'Add <code>* { box-sizing: border-box; }</code>.' : r.doc.querySelector('.card').offsetWidth !== 200 ? 'The card should be exactly 200px wide (including padding and border).' : true) }),
      ] },
      { id: 'classes', title: 'Classes, ids & combining', xp: 25, recap: '<code>.class</code> for groups, <code>#id</code> for one element, <code>a b</code> for “b inside a”.', steps: [
        read('Targeting specific elements', `<p>Give elements a <code>class</code> or <code>id</code> in HTML, then select them in CSS:</p>${pre('<p class="note">…</p>     →   .note { … }\n<div id="hud">…</div>     →   #hud { … }')}`),
        read('Inside something else', `<p>A space between selectors means “inside”. <code>.card h2</code> styles only h2s inside a card. Commas apply one rule to several selectors:</p>${pre('.card h2 { color: gold; }\nh1, h2 { font-family: monospace; }')}`),
        quiz('Which selector targets <code>&lt;button id="play"&gt;</code>?', ['.play', '#play', 'play', 'button.play'], 1),
        code({ page: page('<p class="note">Tip one</p><p>Plain</p><p class="note">Tip two</p><button id="play">Play</button>'), task: 'Make every <code>.note</code> bold (<code>font-weight: bold</code>), and give <code>#play</code> a <code>background-color</code> of <code>gold</code>.', starter: '', hints: ['<code>.note { font-weight: bold; }</code>', '<code>#play { background-color: gold; }</code>'], solution: '.note {\n  font-weight: bold;\n}\n\n#play {\n  background-color: gold;\n}\n',
          check: (r, H) => { const ns = H.els(r, '.note'); if (!ns.every((n) => +r.win.getComputedStyle(n).fontWeight >= 700)) return 'Both .note paragraphs should be bold.'; if (+r.win.getComputedStyle(H.els(r, 'p')[1]).fontWeight >= 700) return 'Only .note paragraphs should be bold.'; return r.css('#play', 'background-color') === 'rgb(255, 215, 0)' || 'Make #play gold.'; } }),
        code({ page: page('<div class="card"><h2>Knight</h2></div><h2>Shop</h2>'), task: 'Make only the <code>h2</code> <b>inside</b> <code>.card</code> the color <code>gold</code> — the “Shop” heading must stay unchanged.', starter: '', hints: ['<code>.card h2 { color: gold; }</code>'], solution: '.card h2 {\n  color: gold;\n}\n',
          check: (r, H) => { const [a, b] = H.els(r, 'h2'); if (r.win.getComputedStyle(a).color !== 'rgb(255, 215, 0)') return 'The h2 inside .card should be gold.'; return r.win.getComputedStyle(b).color !== 'rgb(255, 215, 0)' || 'The “Shop” heading isn’t inside a card, so it shouldn’t be gold.'; } }),
      ] },
      { id: 'text', title: 'Fonts & text', xp: 20, recap: 'font-family, font-size, font-weight, text-align, line-height, letter-spacing.', steps: [
        read('Typography', `<p>Text style makes a huge difference to how a game page feels:</p>${pre('body {\n  font-family: "Courier New", monospace;  /* first choice, then fallback */\n  font-size: 18px;\n  line-height: 1.6;        /* space between lines */\n}\nh1 {\n  text-align: center;\n  letter-spacing: 4px;\n  text-transform: uppercase;\n}')}`),
        quiz('Why list several fonts in <code>font-family</code>?', ['To mix them together', 'If the first isn’t available, the browser tries the next', 'To make text bigger', 'It’s required'], 1),
        code({ page: page('<h1>Game over</h1><p>Your score: 4200. Try again?</p>'), task: 'Center the <code>h1</code>, make it <code>uppercase</code>, and set paragraph <code>font-size</code> to <b>20px</b>.', starter: '', hints: ['<code>text-align: center;</code> and <code>text-transform: uppercase;</code>', '<code>p { font-size: 20px; }</code>'], solution: 'h1 {\n  text-align: center;\n  text-transform: uppercase;\n}\n\np {\n  font-size: 20px;\n}\n',
          check: (r) => (r.css('h1', 'text-align') !== 'center' ? 'Center the h1.' : r.css('h1', 'text-transform') !== 'uppercase' ? 'Make the h1 uppercase.' : r.css('p', 'font-size') !== '20px' ? 'Set the paragraph font-size to 20px.' : true) }),
      ] },
      { id: 'flex', title: 'Flexbox', xp: 35, recap: '<code>display: flex</code> on the parent; <code>justify-content</code> = main axis, <code>align-items</code> = cross axis.', steps: [
        read('Lining things up', `<p>Put <code>display: flex</code> on a <b>parent</b>, and its children line up in a row. Then control spacing and alignment:</p>${pre('.row {\n  display: flex;\n  gap: 10px;                 /* space between items */\n  justify-content: center;   /* along the row */\n  align-items: center;       /* across the row */\n}')}`),
        read('Main axis vs cross axis', `<p>In a row, the <b>main axis</b> runs left→right and <code>justify-content</code> controls it: <code>flex-start</code>, <code>center</code>, <code>space-between</code>, <code>space-around</code>.</p><p>The <b>cross axis</b> runs top→bottom and <code>align-items</code> controls it.</p><p>Change to <code>flex-direction: column</code> and the axes swap!</p>`),
        quiz('Children are in a row. Which property spreads them out horizontally?', ['align-items', 'justify-content', 'text-align', 'flex-wrap'], 1),
        quiz('With <code>flex-direction: column</code>, which property centers items <b>horizontally</b>?', ['justify-content', 'align-items', 'text-align', 'margin'], 1, 'In a column, the cross axis is horizontal.'),
        code({ page: page('<div class="row"><div class="box">1</div><div class="box">2</div><div class="box">3</div></div><style>.box{width:50px;height:50px;background:#7c5cff;color:#fff;display:grid;place-items:center}</style>'), task: 'Make <code>.row</code> a flex container with a <code>gap</code> of <b>12px</b> and <code>justify-content: space-between</code>.', starter: '.row {\n  \n}\n', hints: ['First: <code>display: flex;</code>', 'Then <code>gap: 12px;</code> and <code>justify-content: space-between;</code>'], solution: '.row {\n  display: flex;\n  gap: 12px;\n  justify-content: space-between;\n}\n',
          check: (r) => (r.css('.row', 'display') !== 'flex' ? 'Set <code>display: flex;</code> on .row.' : r.css('.row', 'column-gap') !== '12px' ? 'Add <code>gap: 12px;</code>' : r.css('.row', 'justify-content') !== 'space-between' ? 'Add <code>justify-content: space-between;</code>' : true) }),
        code({ page: page('<div class="menu"><button>Start</button><button>Options</button><button>Quit</button></div><style>.menu{height:200px;background:#111833}</style>'), task: 'Turn <code>.menu</code> into a centered vertical menu: flex, <code>flex-direction: column</code>, centered both ways, with a <b>10px</b> gap.', starter: '.menu {\n  \n}\n', hints: ['<code>display: flex; flex-direction: column;</code>', '<code>justify-content: center; align-items: center; gap: 10px;</code>'], solution: '.menu {\n  display: flex;\n  flex-direction: column;\n  justify-content: center;\n  align-items: center;\n  gap: 10px;\n}\n',
          check: (r) => (r.css('.menu', 'display') !== 'flex' ? 'Use display: flex.' : r.css('.menu', 'flex-direction') !== 'column' ? 'Stack the buttons with flex-direction: column.' : r.css('.menu', 'justify-content') !== 'center' || r.css('.menu', 'align-items') !== 'center' ? 'Center both ways (justify-content and align-items).' : r.css('.menu', 'row-gap') !== '10px' ? 'Add gap: 10px.' : true), success: 'That’s a classic game menu layout.' }),
      ] },
      { id: 'grid', title: 'CSS Grid', xp: 30, recap: '<code>grid-template-columns: repeat(3, 1fr)</code> makes 3 equal columns.', steps: [
        read('Rows and columns', `<p>Flexbox is one direction at a time. <b>Grid</b> does rows <i>and</i> columns — perfect for inventories, level select screens and galleries:</p>${pre('.inventory {\n  display: grid;\n  grid-template-columns: repeat(4, 1fr);\n  gap: 8px;\n}')}<p><code>fr</code> means “a fraction of the free space”. <code>1fr 2fr</code> makes the second column twice as wide.</p>`),
        quiz('What does <code>grid-template-columns: 100px 1fr</code> make?', ['Two equal columns', 'A 100px column and one that fills the rest', '100 columns', 'One column'], 1),
        code({ page: page('<div class="inv">' + '<div class="slot"></div>'.repeat(8) + '</div><style>.slot{height:40px;background:#22d3ee;border-radius:4px}</style>'), task: 'Make <code>.inv</code> a grid with <b>4 equal columns</b> and an <b>8px</b> gap.', starter: '.inv {\n  \n}\n', hints: ['<code>display: grid;</code>', '<code>grid-template-columns: repeat(4, 1fr);</code>'], solution: '.inv {\n  display: grid;\n  grid-template-columns: repeat(4, 1fr);\n  gap: 8px;\n}\n',
          check: (r) => { if (r.css('.inv', 'display') !== 'grid') return 'Set <code>display: grid;</code>'; const cols = r.css('.inv', 'grid-template-columns').split(' ').filter(Boolean); if (cols.length !== 4) return `You have ${cols.length} column(s) — make 4.`; if (new Set(cols).size !== 1) return 'Make the columns equal (1fr each).'; return r.css('.inv', 'row-gap') === '8px' || 'Add <code>gap: 8px;</code>'; } }),
      ] },
      { id: 'position', title: 'Positioning: HUD overlays', xp: 35, recap: '<code>position: relative</code> on the parent, <code>position: absolute</code> + top/left/right/bottom on the child.', steps: [
        read('Placing things on top', `<p>Game HUDs float <b>on top</b> of the game: a score in the corner, a pause button… That’s <b>absolute positioning</b>:</p>${pre('.screen { position: relative; }   /* the anchor */\n.score {\n  position: absolute;\n  top: 8px;\n  right: 8px;\n}')}<p>An absolute element is placed relative to the nearest parent that has a <code>position</code> set — so always set <code>position: relative</code> on the container.</p>`),
        quiz('An absolute element has <code>bottom: 0; left: 0</code>. Where does it go?', ['Top-left of its anchor', 'Bottom-left of its anchor', 'The center', 'Nowhere'], 1),
        code({ page: page('<div class="screen"><canvas width="300" height="150" style="background:#111833;display:block"></canvas><div class="score">Score: 1200</div></div><style>.score{color:#fff;font-family:monospace}</style>'), task: 'Make <code>.screen</code> the anchor, and pin <code>.score</code> to the <b>top-right</b> corner, 8px from each edge.', starter: '.screen {\n  \n}\n\n.score {\n  \n}\n', hints: ['<code>.screen { position: relative; }</code>', '<code>.score { position: absolute; top: 8px; right: 8px; }</code>'], solution: '.screen {\n  position: relative;\n  width: 300px;\n}\n\n.score {\n  position: absolute;\n  top: 8px;\n  right: 8px;\n}\n',
          check: (r) => { if (r.css('.screen', 'position') !== 'relative') return 'Give .screen <code>position: relative</code>.'; if (r.css('.score', 'position') !== 'absolute') return 'Give .score <code>position: absolute</code>.'; const s = r.doc.querySelector('.screen').getBoundingClientRect(), c = r.doc.querySelector('.score').getBoundingClientRect(); return (Math.abs(c.top - s.top - 8) < 1.5 && Math.abs(s.right - c.right - 8) < 1.5) || 'Place it 8px from the top and 8px from the right of the screen.'; } }),
        code({ page: page('<div class="screen"><canvas width="300" height="150" style="background:#111833;display:block"></canvas><div class="lives">♥♥♥</div></div><style>.lives{color:tomato;font-size:20px}</style>'), task: 'Practice: pin <code>.lives</code> to the <b>bottom-left</b> corner, 10px from the edges.', starter: '.screen {\n  position: relative;\n  width: 300px;\n}\n\n', hints: ['<code>position: absolute; bottom: 10px; left: 10px;</code>'], solution: '.screen {\n  position: relative;\n  width: 300px;\n}\n\n.lives {\n  position: absolute;\n  bottom: 10px;\n  left: 10px;\n}\n',
          check: (r) => { if (r.css('.lives', 'position') !== 'absolute') return 'Use position: absolute.'; const s = r.doc.querySelector('.screen').getBoundingClientRect(), c = r.doc.querySelector('.lives').getBoundingClientRect(); return (Math.abs(s.bottom - c.bottom - 10) < 1.5 && Math.abs(c.left - s.left - 10) < 1.5) || 'Place it 10px from the bottom and the left.'; } }),
      ] },
      { id: 'hover', title: 'Hover & transitions', xp: 30, recap: '<code>:hover</code> styles on mouse-over; <code>transition</code> animates the change.', steps: [
        read('Reacting to the mouse', `<p>A <b>pseudo-class</b> like <code>:hover</code> applies styles only in a certain state:</p>${pre('button:hover {\n  background: gold;\n}')}<p>Other useful ones: <code>:active</code> (being clicked), <code>:focus</code> (selected with the keyboard).</p>`),
        read('Smooth changes', `<p>Add <code>transition</code> to the normal state and changes animate instead of snapping:</p>${pre('button {\n  transition: transform 0.15s, background 0.3s;\n}\nbutton:hover {\n  transform: scale(1.1);\n}')}`),
        quiz('Where does the <code>transition</code> property go?', ['Only in :hover', 'On the normal (non-hover) rule', 'In the HTML', 'In JavaScript'], 1, 'On the base rule, so it animates both into and out of hover.'),
        code({ page: page('<button class="btn">Start game</button>'), task: 'Give <code>.btn</code> a <code>transition</code>, and on <code>.btn:hover</code> change its <code>background-color</code>.', starter: '.btn {\n  padding: 10px 20px;\n  background-color: #7c5cff;\n  color: white;\n  border: none;\n}\n', hints: ['Add <code>transition: background-color 0.3s;</code> inside .btn', 'New rule: <code>.btn:hover { background-color: #22d3ee; }</code>'], solution: '.btn {\n  padding: 10px 20px;\n  background-color: #7c5cff;\n  color: white;\n  border: none;\n  transition: background-color 0.3s;\n}\n\n.btn:hover {\n  background-color: #22d3ee;\n}\n',
          check: (r) => { const t = r.css('.btn', 'transition-duration'); if (!t || t.split(',').every((x) => parseFloat(x) === 0)) return 'Add a <code>transition</code> with a duration to .btn.'; return /\.btn:hover\s*\{[^}]*background(-color)?\s*:/.test(r.code) || 'Add a <code>.btn:hover</code> rule that changes the background color.'; } }),
        code({ page: page('<button class="btn">Start game</button>'), keep: true, task: 'Make the button also <b>grow</b> on hover with <code>transform: scale(1.1)</code> (and include <code>transform</code> in the transition).', hints: ['<code>transition: background-color 0.3s, transform 0.15s;</code>'], solution: '.btn {\n  padding: 10px 20px;\n  background-color: #7c5cff;\n  color: white;\n  border: none;\n  transition: background-color 0.3s, transform 0.15s;\n}\n\n.btn:hover {\n  background-color: #22d3ee;\n  transform: scale(1.1);\n}\n',
          check: (r) => (!/\.btn:hover\s*\{[^}]*transform\s*:\s*scale\(\s*1\.1\s*\)/.test(r.code) ? 'Add <code>transform: scale(1.1)</code> in the hover rule.' : !/transition[^;]*transform/.test(r.code) ? 'Include transform in the transition list.' : true) }),
      ] },
      { id: 'anim', title: 'Keyframe animations', xp: 35, recap: '<code>@keyframes</code> defines the steps; <code>animation: name duration timing repeat</code> plays them.', steps: [
        read('Animations that play by themselves', `<p>Transitions need a trigger (like hover). <b>Keyframe animations</b> run on their own — blinking “PRESS START” text, floating logos, spinning coins:</p>${pre('@keyframes blink {\n  from { opacity: 1; }\n  to   { opacity: 0; }\n}\n.press {\n  animation: blink 0.8s ease-in-out infinite alternate;\n}')}<p><code>infinite</code> repeats forever; <code>alternate</code> plays forward then backward.</p>`),
        read('Using percentages', `<p>For more than two steps, use percentages:</p>${pre('@keyframes float {\n  0%   { transform: translateY(0); }\n  50%  { transform: translateY(-10px); }\n  100% { transform: translateY(0); }\n}')}`),
        quiz('Which part makes an animation repeat forever?', ['alternate', 'ease-in-out', 'infinite', '0.8s'], 2),
        code({ page: page('<h1 class="logo">SPACE RAIDERS</h1><p class="press">PRESS START</p>'), task: 'Create a <code>@keyframes blink</code> that goes from <code>opacity: 1</code> to <code>opacity: 0</code>, and apply it to <code>.press</code> lasting <b>0.8s</b>, repeating forever.', starter: '', hints: ['Copy the blink example.', 'Make sure the name in <code>animation</code> matches the @keyframes name.'], solution: '@keyframes blink {\n  from { opacity: 1; }\n  to { opacity: 0; }\n}\n\n.press {\n  animation: blink 0.8s ease-in-out infinite alternate;\n}\n',
          check: (r) => (r.css('.press', 'animation-name') !== 'blink' ? 'Apply <code>animation: blink …</code> to .press.' : r.css('.press', 'animation-duration') !== '0.8s' ? 'Make it last 0.8s.' : r.css('.press', 'animation-iteration-count') !== 'infinite' ? 'Make it repeat forever (infinite).' : !/@keyframes\s+blink[\s\S]*opacity/.test(r.code) ? 'Define <code>@keyframes blink</code> changing opacity.' : true) }),
        code({ page: page('<h1 class="logo">SPACE RAIDERS</h1><p class="press">PRESS START</p>'), keep: true, task: 'Add a second animation, <code>float</code>, that moves <code>.logo</code> up 10px and back (use 0%, 50%, 100%), lasting <b>2s</b>, forever.', hints: ['Copy the float example and apply <code>animation: float 2s ease-in-out infinite;</code> to .logo'], solution: '@keyframes blink {\n  from { opacity: 1; }\n  to { opacity: 0; }\n}\n\n.press {\n  animation: blink 0.8s ease-in-out infinite alternate;\n}\n\n@keyframes float {\n  0% { transform: translateY(0); }\n  50% { transform: translateY(-10px); }\n  100% { transform: translateY(0); }\n}\n\n.logo {\n  animation: float 2s ease-in-out infinite;\n}\n',
          check: (r) => (r.css('.logo', 'animation-name') !== 'float' ? 'Apply the float animation to .logo.' : r.css('.logo', 'animation-duration') !== '2s' ? 'Make it 2s long.' : !/@keyframes\s+float[\s\S]*50%[\s\S]*translateY\(\s*-10px\s*\)/.test(r.code) ? 'At 50% use <code>transform: translateY(-10px)</code>.' : r.css('.logo', 'animation-iteration-count') !== 'infinite' ? 'Repeat forever.' : true), success: 'Your title screen is alive!' }),
      ] },
      { id: 'project', title: 'Project: arcade title screen', xp: 60, recap: 'Flexbox centering, positioning, hover and keyframes combined into a polished screen.', steps: [
        read('Style a full title screen', `<p>Below is the HTML for a game title screen. Your job: make it look like a real arcade game, in three steps.</p>`),
        code({ page: page('<div class="title"><h1>STAR DODGER</h1><nav class="menu"><button>Play</button><button>Scores</button><button>Quit</button></nav><p class="best">Best: 9001</p></div>'), task: '<b>Step 1.</b> Make <code>.title</code> fill <b>300px</b> of height with a dark background (<code>#0b1020</code>), and center everything with flexbox in a column.', starter: '', hints: ['<code>height: 300px; background: #0b1020;</code>', '<code>display: flex; flex-direction: column; justify-content: center; align-items: center;</code>'], solution: '.title {\n  height: 300px;\n  background: #0b1020;\n  display: flex;\n  flex-direction: column;\n  justify-content: center;\n  align-items: center;\n}\n',
          check: (r) => (r.doc.querySelector('.title').offsetHeight !== 300 ? 'Make .title 300px tall.' : r.css('.title', 'background-color') !== rgb('#0b1020') ? 'Use background #0b1020.' : r.css('.title', 'display') !== 'flex' || r.css('.title', 'flex-direction') !== 'column' ? 'Use flex in a column.' : r.css('.title', 'align-items') !== 'center' || r.css('.title', 'justify-content') !== 'center' ? 'Center both ways.' : true) }),
        code({ page: page('<div class="title"><h1>STAR DODGER</h1><nav class="menu"><button>Play</button><button>Scores</button><button>Quit</button></nav><p class="best">Best: 9001</p></div>'), keep: true, task: '<b>Step 2.</b> Make the h1 <code>gold</code> with <code>letter-spacing: 4px</code>. Stack the menu buttons in a column with a <b>8px</b> gap, and on hover give buttons a <code>gold</code> background.', hints: ['<code>.menu { display: flex; flex-direction: column; gap: 8px; }</code>', '<code>.menu button:hover { background: gold; }</code>'], solution: '.title {\n  height: 300px;\n  background: #0b1020;\n  display: flex;\n  flex-direction: column;\n  justify-content: center;\n  align-items: center;\n}\n\nh1 {\n  color: gold;\n  letter-spacing: 4px;\n}\n\n.menu {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n\n.menu button {\n  transition: background 0.2s;\n}\n\n.menu button:hover {\n  background: gold;\n}\n',
          check: (r) => (r.css('h1', 'color') !== 'rgb(255, 215, 0)' ? 'Make the h1 gold.' : r.css('h1', 'letter-spacing') !== '4px' ? 'Add letter-spacing: 4px to the h1.' : r.css('.menu', 'flex-direction') !== 'column' || r.css('.menu', 'row-gap') !== '8px' ? 'Stack the menu in a column with an 8px gap.' : !/button:hover\s*\{[^}]*background(-color)?\s*:\s*gold/.test(r.code) ? 'Give buttons a gold background on hover.' : true) }),
        code({ page: page('<div class="title"><h1>STAR DODGER</h1><nav class="menu"><button>Play</button><button>Scores</button><button>Quit</button></nav><p class="best">Best: 9001</p></div>'), keep: true, task: '<b>Step 3.</b> Make <code>.title</code> <code>position: relative</code>, pin <code>.best</code> to the bottom-right (10px), and make the h1 pulse with a <code>@keyframes pulse</code> that scales to <b>1.05</b> and back, forever.', hints: ['<code>.best { position: absolute; bottom: 10px; right: 10px; }</code>', '<code>@keyframes pulse { 50% { transform: scale(1.05); } }</code> and <code>animation: pulse 1.5s infinite;</code>'], solution: '.title {\n  position: relative;\n  height: 300px;\n  background: #0b1020;\n  display: flex;\n  flex-direction: column;\n  justify-content: center;\n  align-items: center;\n}\n\nh1 {\n  color: gold;\n  letter-spacing: 4px;\n  animation: pulse 1.5s ease-in-out infinite;\n}\n\n@keyframes pulse {\n  50% { transform: scale(1.05); }\n}\n\n.menu {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n\n.menu button {\n  transition: background 0.2s;\n}\n\n.menu button:hover {\n  background: gold;\n}\n\n.best {\n  position: absolute;\n  bottom: 10px;\n  right: 10px;\n  color: white;\n}\n',
          check: (r) => { if (r.css('.title', 'position') !== 'relative') return 'Give .title position: relative.'; if (r.css('.best', 'position') !== 'absolute' || r.css('.best', 'bottom') !== '10px' || r.css('.best', 'right') !== '10px') return 'Pin .best 10px from the bottom-right.'; if (r.css('h1', 'animation-name') !== 'pulse' || r.css('h1', 'animation-iteration-count') !== 'infinite') return 'Animate the h1 with pulse, forever.'; return /@keyframes\s+pulse[\s\S]*scale\(\s*1\.05\s*\)/.test(r.code) || 'The pulse keyframes should scale to 1.05.'; }, success: 'That looks like a real arcade title screen! 🕹️' }),
      ] },
    ],
  });

  /* ============================== DOM ============================== */
  const domPage = (b) => `<!DOCTYPE html><html><head><style>body{font-family:system-ui;padding:12px}button{padding:6px 14px}</style></head><body>${b}</body></html>`;
  course({
    id: 'dom', lang: 'javascript', order: 3, title: 'Interactive Pages & UI', badge: 'DOM', color: '#f59e0b', ext: 'js', run: 'web', mode: 'dom',
    desc: 'Buttons, menus, clicker games', desc2: 'Connect JavaScript to HTML: react to clicks, update text and build a clicker game with upgrades.', related: ['html'],
    lessons: [
      { id: 'select', title: 'Find & change elements', xp: 25, recap: '<code>document.querySelector()</code> finds; <code>.textContent</code> and <code>.style</code> change.', steps: [
        read('The DOM', `<p>When a page loads, the browser turns the HTML into objects JavaScript can control — the <b>DOM</b> (Document Object Model). Find an element with a CSS selector, then change it:</p>${pre('const title = document.querySelector("#title");\ntitle.textContent = "Level 2";\ntitle.style.color = "gold";')}${tip('Same selectors as CSS: <code>#id</code>, <code>.class</code>, <code>tag</code>.')}`),
        quiz('<code>document.querySelector(".coin")</code> returns…', ['Every element with class coin', 'The first element with class coin', 'The id coin', 'A number'], 1, 'Use <code>querySelectorAll</code> to get all of them.'),
        code({ page: domPage('<h1 id="title">Level 1</h1><p class="msg">Ready?</p>'), task: 'Change the text of <code>#title</code> to <b>Level 2</b>.', starter: '// find the heading and change its text\n', hints: ['<code>document.querySelector("#title")</code> finds it.', 'Set <code>.textContent = "Level 2"</code>'], solution: 'const title = document.querySelector("#title");\ntitle.textContent = "Level 2";\n',
          check: (r, H) => H.text(r, '#title') === 'Level 2' || `The heading says “${e(H.text(r, '#title'))}”.` }),
        code({ page: domPage('<h1 id="title">Level 1</h1><p class="msg">Ready?</p>'), keep: true, task: 'Now make the <code>.msg</code> paragraph say <b>Go!</b> and color it <code>green</code> with <code>.style.color</code>.', hints: ['<code>const msg = document.querySelector(".msg");</code>'], solution: 'const title = document.querySelector("#title");\ntitle.textContent = "Level 2";\nconst msg = document.querySelector(".msg");\nmsg.textContent = "Go!";\nmsg.style.color = "green";\n',
          check: (r, H) => (H.text(r, '.msg') !== 'Go!' ? 'Make .msg say “Go!”.' : r.css('.msg', 'color') !== 'rgb(0, 128, 0)' ? 'Make .msg green.' : true) }),
      ] },
      { id: 'events', title: 'Reacting to clicks', xp: 30, recap: '<code>el.addEventListener("click", () => { … })</code> runs code every click.', steps: [
        read('Events', `<p>Pages become games when they <b>react</b>. Listen for an event and give a function to run:</p>${pre('const btn = document.querySelector("#attack");\nbtn.addEventListener("click", () => {\n  console.log("Swing!");\n});')}<p>The arrow function <code>() => { … }</code> runs <b>every time</b> the event happens — not when the page loads.</p>`),
        quiz('When does the function passed to addEventListener run?', ['Immediately', 'Every time the event happens', 'Only the first time', 'When the page closes'], 1),
        code({ page: domPage('<button id="btn">+1 gold</button><p id="gold">0</p>'), task: 'When <code>#btn</code> is clicked, add 1 to the number shown in <code>#gold</code>.', starter: 'let gold = 0;\nconst btn = document.querySelector("#btn");\nconst goldText = document.querySelector("#gold");\n\n', hints: ['<code>btn.addEventListener("click", () => { … });</code>', 'Inside: <code>gold++; goldText.textContent = gold;</code>'], solution: 'let gold = 0;\nconst btn = document.querySelector("#btn");\nconst goldText = document.querySelector("#gold");\n\nbtn.addEventListener("click", () => {\n  gold++;\n  goldText.textContent = gold;\n});\n',
          check: (r, H) => { const b = H.el(r, '#btn'); b.click(); b.click(); b.click(); return H.text(r, '#gold') === '3' || `I clicked 3 times and it shows “${e(H.text(r, '#gold'))}”.`; }, success: 'Click it in the live preview — it works!' }),
        code({ page: domPage('<p id="hp">HP: 10</p><button id="hit">Take hit</button><button id="heal">Heal</button>'), task: 'Practice: <code>#hit</code> removes 3 HP and <code>#heal</code> adds 2 HP. Keep HP between <b>0 and 10</b>, and show it as <b>HP: N</b>.', starter: 'let hp = 10;\nconst hpText = document.querySelector("#hp");\n\nfunction show() {\n  hpText.textContent = "HP: " + hp;\n}\n', hints: ['Two listeners, one per button.', 'Clamp with <code>Math.max(0, …)</code> and <code>Math.min(10, …)</code>, then call <code>show()</code>.'], solution: 'let hp = 10;\nconst hpText = document.querySelector("#hp");\n\nfunction show() {\n  hpText.textContent = "HP: " + hp;\n}\n\ndocument.querySelector("#hit").addEventListener("click", () => {\n  hp = Math.max(0, hp - 3);\n  show();\n});\n\ndocument.querySelector("#heal").addEventListener("click", () => {\n  hp = Math.min(10, hp + 2);\n  show();\n});\n',
          check: (r, H) => { const hit = H.el(r, '#hit'), heal = H.el(r, '#heal'); hit.click(); if (H.text(r, '#hp') !== 'HP: 7') return 'One hit should show “HP: 7”.'; heal.click(); heal.click(); if (H.text(r, '#hp') !== 'HP: 10') return 'HP should never go above 10.'; for (let i = 0; i < 5; i++) hit.click(); return H.text(r, '#hp') === 'HP: 0' || 'HP should never go below 0.'; } }),
      ] },
      { id: 'create', title: 'Creating elements', xp: 30, recap: '<code>createElement</code> → set content → <code>append</code>.', steps: [
        read('Building the page with code', `<p>You can create brand-new elements from JavaScript — perfect for lists that change, like an inventory or a chat log:</p>${pre('const li = document.createElement("li");\nli.textContent = "Iron sword";\ndocument.querySelector("#inventory").append(li);')}`),
        code({ page: domPage('<ul id="inv"></ul>'), task: 'Use a loop to add an <code>&lt;li&gt;</code> for each item in the array to <code>#inv</code>.', starter: 'const items = ["sword", "shield", "potion", "map"];\nconst inv = document.querySelector("#inv");\n\n', hints: ['<code>for (const item of items) { … }</code>', 'Inside: create an li, set its textContent, then <code>inv.append(li)</code>.'], solution: 'const items = ["sword", "shield", "potion", "map"];\nconst inv = document.querySelector("#inv");\n\nfor (const item of items) {\n  const li = document.createElement("li");\n  li.textContent = item;\n  inv.append(li);\n}\n',
          check: (r, H) => { const lis = H.els(r, '#inv li').map((l) => l.textContent.trim()); return lis.join() === 'sword,shield,potion,map' || `The list has: ${lis.length ? lis.join(', ') : 'nothing'}.`; } }),
        code({ page: domPage('<ul id="inv"></ul><button id="loot">Loot chest</button>'), task: 'Clicking <code>#loot</code> should add a random item from <code>loot</code> to the list. Write <code>addItem(name)</code> and use it in the click listener.', starter: 'const loot = ["gem", "gold", "key", "bomb"];\nconst inv = document.querySelector("#inv");\n\nfunction addItem(name) {\n  \n}\n\n', hints: ['addItem: create li, set text, append.', 'Random item: <code>loot[Math.floor(Math.random() * loot.length)]</code>'], solution: 'const loot = ["gem", "gold", "key", "bomb"];\nconst inv = document.querySelector("#inv");\n\nfunction addItem(name) {\n  const li = document.createElement("li");\n  li.textContent = name;\n  inv.append(li);\n}\n\ndocument.querySelector("#loot").addEventListener("click", () => {\n  addItem(loot[Math.floor(Math.random() * loot.length)]);\n});\n',
          check: (r, H) => { r.win.addItem('test'); if (H.text(r, '#inv li') !== 'test') return 'addItem("test") should add an li with “test”.'; const b = H.el(r, '#loot'); for (let i = 0; i < 20; i++) b.click(); const t = H.els(r, '#inv li').slice(1).map((l) => l.textContent); if (t.length !== 20) return 'Each click should add one item.'; return t.every((x) => ['gem', 'gold', 'key', 'bomb'].includes(x)) && new Set(t).size > 1 || 'Pick a random item from loot each time.'; } }),
      ] },
      { id: 'input', title: 'Reading what players type', xp: 30, recap: '<code>input.value</code> is the text in a box; <code>input.value = ""</code> clears it.', steps: [
        read('Input values', `<p>Read what someone typed with <code>.value</code>. It’s always a <b>string</b>, so convert numbers with <code>Number()</code>:</p>${pre('const name = document.querySelector("#name").value;\nconst age = Number(document.querySelector("#age").value);')}`),
        predict('// the input contains: 5\nconst v = document.querySelector("#n").value;\nconsole.log(v + 1);', ['6', '51', 'NaN', 'Error'], 1, 'value is the string "5", and "5" + 1 joins text → "51". Use Number(v) + 1.'),
        code({ page: domPage('<input id="name" placeholder="Hero name"> <button id="go">Start</button><h2 id="hello"></h2>'), task: 'When <code>#go</code> is clicked, show <b>Welcome, NAME!</b> in <code>#hello</code> (using what was typed). If the box is empty, show <b>Welcome, Hero!</b>.', starter: 'const input = document.querySelector("#name");\nconst hello = document.querySelector("#hello");\n\n', hints: ['<code>const name = input.value.trim() || "Hero";</code>', 'Use a template literal for the message.'], solution: 'const input = document.querySelector("#name");\nconst hello = document.querySelector("#hello");\n\ndocument.querySelector("#go").addEventListener("click", () => {\n  const name = input.value.trim() || "Hero";\n  hello.textContent = `Welcome, ${name}!`;\n});\n',
          check: (r, H) => { const i = H.el(r, '#name'), b = H.el(r, '#go'); i.value = 'Zelda'; b.click(); if (H.text(r, '#hello') !== 'Welcome, Zelda!') return 'With “Zelda” typed, it should show “Welcome, Zelda!”.'; i.value = '  '; b.click(); return H.text(r, '#hello') === 'Welcome, Hero!' || 'With an empty box, show “Welcome, Hero!”.'; } }),
      ] },
      { id: 'clicker', title: 'Project: a clicker game', xp: 70, recap: 'State in variables, a render function, events, timers and upgrades: the structure of every idle game.', steps: [
        read('Build an idle clicker', `<p>Clicker games (Cookie Clicker, Adventure Capitalist) are perfect first projects: simple rules, real progression. You’ll build one in three steps.</p><p>A key pattern: keep game data in variables and write one <code>render()</code> function that updates the screen from them. Change data → call render.</p>`),
        code({ page: domPage('<h1><span id="coins">0</span> coins</h1><button id="mine">⛏ Mine</button><p id="info"></p><button id="buy">Buy pickaxe</button>'), task: '<b>Step 1.</b> Clicking <b>Mine</b> adds <code>perClick</code> coins. Write <code>render()</code> to show the coins, and call it after each click.', starter: 'let coins = 0;\nlet perClick = 1;\n\nfunction render() {\n  \n}\n\n', hints: ['render: <code>document.querySelector("#coins").textContent = coins;</code>', 'Listener on #mine: <code>coins += perClick; render();</code>'], solution: 'let coins = 0;\nlet perClick = 1;\n\nfunction render() {\n  document.querySelector("#coins").textContent = coins;\n}\n\ndocument.querySelector("#mine").addEventListener("click", () => {\n  coins += perClick;\n  render();\n});\n',
          check: (r, H) => { const m = H.el(r, '#mine'); m.click(); m.click(); if (H.text(r, '#coins') !== '2') return 'Two clicks should show 2 coins.'; r.win.eval('perClick = 5'); m.click(); return H.text(r, '#coins') === '7' || 'Each click should add perClick coins.'; } }),
        code({ page: domPage('<h1><span id="coins">0</span> coins</h1><button id="mine">⛏ Mine</button><p id="info"></p><button id="buy">Buy pickaxe</button>'), keep: true, task: '<b>Step 2.</b> Add an upgrade: <code>let price = 10;</code>. Clicking <b>Buy pickaxe</b> costs <code>price</code> coins (only if you can afford it), adds 1 to <code>perClick</code>, and makes the next one cost <b>double</b>. Show “Pickaxe costs N” in <code>#info</code> inside render.', hints: ['<code>if (coins >= price) { coins -= price; perClick++; price *= 2; render(); }</code>', 'In render: <code>document.querySelector("#info").textContent = "Pickaxe costs " + price;</code>'], solution: 'let coins = 0;\nlet perClick = 1;\nlet price = 10;\n\nfunction render() {\n  document.querySelector("#coins").textContent = coins;\n  document.querySelector("#info").textContent = "Pickaxe costs " + price;\n}\n\ndocument.querySelector("#mine").addEventListener("click", () => {\n  coins += perClick;\n  render();\n});\n\ndocument.querySelector("#buy").addEventListener("click", () => {\n  if (coins >= price) {\n    coins -= price;\n    perClick++;\n    price *= 2;\n    render();\n  }\n});\nrender();\n',
          check: (r, H) => { r.win.eval('coins = 5; perClick = 1; price = 10'); r.win.render(); H.el(r, '#buy').click(); if (H.get(r, 'perClick') !== 1) return 'You shouldn’t be able to buy without enough coins.'; r.win.eval('coins = 25'); H.el(r, '#buy').click(); if (H.get(r, 'coins') !== 15 || H.get(r, 'perClick') !== 2 || H.get(r, 'price') !== 20) return 'Buying should cost 10, add 1 to perClick and double the price to 20.'; return /Pickaxe costs 20/.test(H.text(r, '#info')) || 'Show “Pickaxe costs 20” in #info.'; } }),
        code({ page: domPage('<h1><span id="coins">0</span> coins</h1><button id="mine">⛏ Mine</button><p id="info"></p><button id="buy">Buy pickaxe</button>'), keep: true, task: '<b>Step 3.</b> Make it idle: every <b>1 second</b>, add <code>perClick</code> coins automatically using <code>setInterval</code>, then render. Also disable the buy button when you can’t afford it (<code>button.disabled = coins &lt; price</code>) in render.', hints: ['<code>setInterval(() => { coins += perClick; render(); }, 1000);</code>', 'In render: <code>document.querySelector("#buy").disabled = coins < price;</code>'], solution: 'let coins = 0;\nlet perClick = 1;\nlet price = 10;\n\nfunction render() {\n  document.querySelector("#coins").textContent = coins;\n  document.querySelector("#info").textContent = "Pickaxe costs " + price;\n  document.querySelector("#buy").disabled = coins < price;\n}\n\ndocument.querySelector("#mine").addEventListener("click", () => {\n  coins += perClick;\n  render();\n});\n\ndocument.querySelector("#buy").addEventListener("click", () => {\n  if (coins >= price) {\n    coins -= price;\n    perClick++;\n    price *= 2;\n    render();\n  }\n});\n\nsetInterval(() => {\n  coins += perClick;\n  render();\n}, 1000);\nrender();\n',
          check: (r, H) => { if (!/setInterval\s*\(/.test(r.code) || !/1000/.test(r.code)) return 'Use <code>setInterval(…, 1000)</code>.'; r.win.eval('coins = 3; price = 10'); r.win.render(); if (!H.el(r, '#buy').disabled) return 'The buy button should be disabled when you can’t afford it.'; r.win.eval('coins = 30'); r.win.render(); return !H.el(r, '#buy').disabled || 'Enable the button when you can afford it.'; }, success: 'You built an idle game — the same loop powers games with millions of players.' }),
      ] },
    ],
  });
})();
